DB_NAME='Шагеева_РР_Страховая_компания.odb'
DDL=[]
def table(name,body): DDL.append(f'CREATE TABLE "{name}" ({body})')
def digits(field,n): return f'CHECK ("{field}" SIMILAR TO \'[0-9]{{{n}}}\')'

table('Пол', '''"Код пола" CHAR(1) NOT NULL PRIMARY KEY CHECK ("Код пола" IN ('1','2')),
"Наименование пола" VARCHAR(7) NOT NULL UNIQUE,
"Обозначение" CHAR(1) NOT NULL UNIQUE,
CHECK (("Код пола"='1' AND "Наименование пола"='мужской' AND "Обозначение"='M') OR
       ("Код пола"='2' AND "Наименование пола"='женский' AND "Обозначение"='F'))''')
table('Справочник валют',f'''"Код валюты" CHAR(3) NOT NULL PRIMARY KEY {digits('Код валюты',3)},
"Буквенный код" CHAR(3) NOT NULL UNIQUE CHECK ("Буквенный код" SIMILAR TO '[A-Z]{{3}}'),
"Наименование валюты" VARCHAR(50) NOT NULL UNIQUE CHECK (CHAR_LENGTH(TRIM("Наименование валюты"))>0)''')
table('Курс валюты','''"Код валюты" CHAR(3) NOT NULL,
"Дата курса" DATE NOT NULL CHECK ("Дата курса"<=CURRENT_DATE),
"Курс" DECIMAL(12,2) NOT NULL CHECK ("Курс">0),
PRIMARY KEY ("Код валюты","Дата курса"),
FOREIGN KEY ("Код валюты") REFERENCES "Справочник валют" ("Код валюты") ON UPDATE CASCADE''')
table('Справочник стран',f'''"Код ОКСМ" CHAR(3) NOT NULL PRIMARY KEY {digits('Код ОКСМ',3)},
"Наименование страны" VARCHAR(100) NOT NULL UNIQUE CHECK (CHAR_LENGTH(TRIM("Наименование страны"))>0),
"Код валюты" CHAR(3) NOT NULL,
"Страховое покрытие" INTEGER NOT NULL CHECK ("Страховое покрытие">0),
"Коэффициент" DECIMAL(5,2) NOT NULL CHECK ("Коэффициент">0),
FOREIGN KEY ("Код валюты") REFERENCES "Справочник валют" ("Код валюты") ON UPDATE CASCADE''')
table('Справочник категорий услуг',f'''"Код категории" CHAR(2) NOT NULL PRIMARY KEY {digits('Код категории',2)},
"Наименование категории" VARCHAR(30) NOT NULL UNIQUE CHECK (CHAR_LENGTH(TRIM("Наименование категории"))>0)''')
table('Услуга',f'''"Код услуги" CHAR(3) NOT NULL PRIMARY KEY {digits('Код услуги',3)},
"Код категории" CHAR(2) NOT NULL,
"Наименование услуги" VARCHAR(50) NOT NULL CHECK (CHAR_LENGTH(TRIM("Наименование услуги"))>0),
FOREIGN KEY ("Код категории") REFERENCES "Справочник категорий услуг" ("Код категории") ON UPDATE CASCADE''')
table('Стоимость услуг','''"Код услуги" CHAR(3) NOT NULL,
"Дата стоимости" DATE NOT NULL CHECK ("Дата стоимости"<=CURRENT_DATE),
"Базовая стоимость" DECIMAL(12,2) NOT NULL CHECK ("Базовая стоимость">0),
PRIMARY KEY ("Код услуги","Дата стоимости"),
FOREIGN KEY ("Код услуги") REFERENCES "Услуга" ("Код услуги") ON UPDATE CASCADE''')
table('Клиент',f'''"Номер паспорта" CHAR(9) NOT NULL PRIMARY KEY {digits('Номер паспорта',9)},
"ФИО клиента" VARCHAR(40) NOT NULL CHECK (REPLACE("ФИО клиента",'-',' ') SIMILAR TO '[A-Za-z ]+' AND CHAR_LENGTH(TRIM(REPLACE("ФИО клиента",'-',' ')))>0),
"Дата рождения" DATE NOT NULL CHECK (DATEADD(18 YEAR TO "Дата рождения")<=CURRENT_DATE),
"Код пола" CHAR(1) NOT NULL,
"Дата выдачи" DATE NOT NULL CHECK ("Дата выдачи"<=CURRENT_DATE),
"Действителен до" DATE NOT NULL CHECK ("Действителен до">CURRENT_DATE),
CHECK ("Дата выдачи">"Дата рождения" AND "Действителен до">"Дата выдачи"),
FOREIGN KEY ("Код пола") REFERENCES "Пол" ("Код пола") ON UPDATE CASCADE''')
table('Страховой агент',f'''"Код агента" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
"ФИО агента" VARCHAR(100) NOT NULL CHECK (CHAR_LENGTH(TRIM("ФИО агента"))>0),
"Паспорт агента" CHAR(10) NOT NULL UNIQUE {digits('Паспорт агента',10)},
"Дата выдачи" DATE NOT NULL CHECK ("Дата выдачи"<=CURRENT_DATE),
"Кем выдан" VARCHAR(200) NOT NULL,
"Активен" SMALLINT DEFAULT 1 NOT NULL CHECK ("Активен" IN (0,1))''')
table('Договор агента',f'''"Номер договора" VARCHAR(20) NOT NULL PRIMARY KEY,
"Код агента" INTEGER NOT NULL,
"Дата договора" DATE DEFAULT CURRENT_DATE NOT NULL,
"Начало договора" DATE NOT NULL,
"Окончание договора" DATE NOT NULL,
"Процент комиссии" DECIMAL(5,2) NOT NULL CHECK ("Процент комиссии">=0 AND "Процент комиссии"<=100),
"БИК" CHAR(9) NOT NULL {digits('БИК',9)},
"Счёт" CHAR(20) NOT NULL {digits('Счёт',20)},
"Наименование банка" VARCHAR(100) NOT NULL,
CHECK ("Начало договора">="Дата договора" AND "Окончание договора">="Начало договора"),
FOREIGN KEY ("Код агента") REFERENCES "Страховой агент" ("Код агента")''')
table('Страховой полис','''"Номер полиса" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
"Номер паспорта" CHAR(9) NOT NULL,
"Дата оформления" DATE DEFAULT CURRENT_DATE NOT NULL CHECK ("Дата оформления"<=CURRENT_DATE),
"Начало действия" DATE NOT NULL,
"Окончание действия" DATE NOT NULL,
"Код ОКСМ" CHAR(3) NOT NULL,
"Номер договора" VARCHAR(20) NOT NULL,
"Коэффициент полиса" DECIMAL(5,2) NOT NULL CHECK ("Коэффициент полиса">0),
"Покрытие полиса" INTEGER NOT NULL CHECK ("Покрытие полиса">0),
"Валюта полиса" CHAR(3) NOT NULL,
"Курс полиса" DECIMAL(12,2) NOT NULL CHECK ("Курс полиса">0),
"Дата курса" DATE NOT NULL,
CHECK ("Начало действия">="Дата оформления"),
CHECK ("Окончание действия">=DATEADD(7 DAY TO "Начало действия")),
FOREIGN KEY ("Номер паспорта") REFERENCES "Клиент" ("Номер паспорта") ON UPDATE CASCADE,
FOREIGN KEY ("Код ОКСМ") REFERENCES "Справочник стран" ("Код ОКСМ") ON UPDATE CASCADE,
FOREIGN KEY ("Номер договора") REFERENCES "Договор агента" ("Номер договора"),
FOREIGN KEY ("Валюта полиса","Дата курса") REFERENCES "Курс валюты" ("Код валюты","Дата курса")''')
table('Услуги в полисе клиента','''"Номер полиса" INTEGER NOT NULL,
"Код услуги" CHAR(3) NOT NULL,
"Дата тарифа" DATE NOT NULL,
"Цена услуги" DECIMAL(12,2) NOT NULL CHECK ("Цена услуги">0),
PRIMARY KEY ("Номер полиса","Код услуги"),
FOREIGN KEY ("Номер полиса") REFERENCES "Страховой полис" ("Номер полиса") ON DELETE CASCADE,
FOREIGN KEY ("Код услуги","Дата тарифа") REFERENCES "Стоимость услуг" ("Код услуги","Дата стоимости") ON UPDATE CASCADE''')
for code,msg in [('E_AGE','На дату оформления клиенту должно быть 18 лет'),('E_PASSPORT','Паспорт должен действовать весь срок поездки'),('E_CONTRACT','Дата оформления вне срока договора агента'),('E_RATE','Нет курса на дату оформления'),('E_PRICE','Нет тарифа услуги на дату оформления'),('E_HISTORY','Дата оформления и страна полиса с услугами неизменяемы')]:
 DDL.append(f"CREATE EXCEPTION {code} '{msg}'")
DDL.append('''CREATE TRIGGER BIU_POLICY FOR "Страховой полис" ACTIVE BEFORE INSERT OR UPDATE POSITION 0 AS
DECLARE VARIABLE DOB DATE; DECLARE VARIABLE ISSUED DATE; DECLARE VARIABLE EXPIRY DATE;
DECLARE VARIABLE D1 DATE; DECLARE VARIABLE D2 DATE;
BEGIN
 SELECT "Дата рождения","Дата выдачи","Действителен до" FROM "Клиент" WHERE "Номер паспорта"=NEW."Номер паспорта" INTO :DOB,:ISSUED,:EXPIRY;
 IF (DATEADD(18 YEAR TO :DOB)>NEW."Дата оформления") THEN EXCEPTION E_AGE;
 IF (:ISSUED>NEW."Дата оформления" OR :EXPIRY<NEW."Окончание действия") THEN EXCEPTION E_PASSPORT;
 SELECT "Начало договора","Окончание договора" FROM "Договор агента" WHERE "Номер договора"=NEW."Номер договора" INTO :D1,:D2;
 IF (NEW."Дата оформления"<:D1 OR NEW."Дата оформления">:D2) THEN EXCEPTION E_CONTRACT;
 IF (UPDATING AND (NEW."Дата оформления"<>OLD."Дата оформления" OR NEW."Код ОКСМ"<>OLD."Код ОКСМ")) THEN
  IF (EXISTS(SELECT 1 FROM "Услуги в полисе клиента" WHERE "Номер полиса"=OLD."Номер полиса")) THEN EXCEPTION E_HISTORY;
 IF (INSERTING OR NEW."Дата оформления"<>OLD."Дата оформления" OR NEW."Код ОКСМ"<>OLD."Код ОКСМ") THEN BEGIN
  SELECT "Коэффициент","Страховое покрытие","Код валюты" FROM "Справочник стран" WHERE "Код ОКСМ"=NEW."Код ОКСМ" INTO NEW."Коэффициент полиса",NEW."Покрытие полиса",NEW."Валюта полиса";
  SELECT MAX("Дата курса") FROM "Курс валюты" WHERE "Код валюты"=NEW."Валюта полиса" AND "Дата курса"<=NEW."Дата оформления" INTO NEW."Дата курса";
  IF (NEW."Дата курса" IS NULL) THEN EXCEPTION E_RATE;
  SELECT "Курс" FROM "Курс валюты" WHERE "Код валюты"=NEW."Валюта полиса" AND "Дата курса"=NEW."Дата курса" INTO NEW."Курс полиса";
 END
END''')
DDL.append('''CREATE TRIGGER BIU_SERVICE FOR "Услуги в полисе клиента" ACTIVE BEFORE INSERT OR UPDATE POSITION 0 AS
DECLARE VARIABLE ISSUED DATE;
BEGIN
 IF (INSERTING OR NEW."Код услуги"<>OLD."Код услуги" OR NEW."Номер полиса"<>OLD."Номер полиса") THEN BEGIN
  SELECT "Дата оформления" FROM "Страховой полис" WHERE "Номер полиса"=NEW."Номер полиса" INTO :ISSUED;
  SELECT MAX("Дата стоимости") FROM "Стоимость услуг" WHERE "Код услуги"=NEW."Код услуги" AND "Дата стоимости"<=:ISSUED INTO NEW."Дата тарифа";
  IF (NEW."Дата тарифа" IS NULL) THEN EXCEPTION E_PRICE;
  SELECT "Базовая стоимость" FROM "Стоимость услуг" WHERE "Код услуги"=NEW."Код услуги" AND "Дата стоимости"=NEW."Дата тарифа" INTO NEW."Цена услуги";
 END
END''')
DAILY='COALESCE((SELECT SUM(j."Цена услуги") FROM "Услуги в полисе клиента" j WHERE j."Номер полиса"=p."Номер полиса"),0)'
DETAIL=f'''SELECT p."Номер полиса",p."Дата оформления",p."Начало действия",p."Окончание действия",c."Номер паспорта",c."ФИО клиента",c."Дата рождения",g."Обозначение" AS "Пол",s."Наименование страны",p."Покрытие полиса",v."Буквенный код" AS "Валюта",p."Коэффициент полиса",p."Курс полиса",p."Дата курса",
DATEDIFF(DAY FROM p."Начало действия" TO p."Окончание действия") AS "Дней",
CAST({DAILY} AS DECIMAL(12,2)) AS "Услуги в день",
CAST(ROUND({DAILY}*p."Коэффициент полиса"*DATEDIFF(DAY FROM p."Начало действия" TO p."Окончание действия"),2) AS DECIMAL(14,2)) AS "Стоимость полиса",
CAST(p."Покрытие полиса"*p."Курс полиса" AS DECIMAL(16,2)) AS "Покрытие в рублях",
a."Код агента",a."ФИО агента",d."Номер договора",d."Процент комиссии"
FROM "Страховой полис" p JOIN "Клиент" c ON c."Номер паспорта"=p."Номер паспорта"
JOIN "Пол" g ON g."Код пола"=c."Код пола"
JOIN "Справочник стран" s ON s."Код ОКСМ"=p."Код ОКСМ"
JOIN "Справочник валют" v ON v."Код валюты"=p."Валюта полиса"
JOIN "Договор агента" d ON d."Номер договора"=p."Номер договора"
JOIN "Страховой агент" a ON a."Код агента"=d."Код агента"'''
DDL.append('CREATE VIEW "Расчёт полисов" AS '+DETAIL)
QUERIES={
'01_Клиенты_и_все_полисы': 'SELECT "Номер паспорта","ФИО клиента","Дата рождения","Пол","Номер полиса","Дата оформления","Наименование страны","Покрытие полиса","Валюта" FROM "Расчёт полисов" ORDER BY "Номер полиса"',
'02_Все_клиенты_включая_без_полисов': '''SELECT c."Номер паспорта",c."ФИО клиента",c."Дата рождения",g."Наименование пола"||' ('||g."Обозначение"||')' AS "Пол",p."Номер полиса",p."Дата оформления",s."Наименование страны",p."Покрытие полиса",v."Буквенный код" FROM "Клиент" c JOIN "Пол" g ON g."Код пола"=c."Код пола" LEFT JOIN "Страховой полис" p ON p."Номер паспорта"=c."Номер паспорта" LEFT JOIN "Справочник стран" s ON s."Код ОКСМ"=p."Код ОКСМ" LEFT JOIN "Справочник валют" v ON v."Код валюты"=p."Валюта полиса" ORDER BY c."Номер паспорта",p."Номер полиса"''',
'03_Количество_полисов_текущий_год': '''SELECT COUNT(*) AS "Всего полисов" FROM "Страховой полис" WHERE EXTRACT(YEAR FROM "Дата оформления")=EXTRACT(YEAR FROM CURRENT_DATE)''',
'04_Клиенты_с_полисами_текущий_год': '''SELECT c."Номер паспорта",c."ФИО клиента",c."Дата рождения",COUNT(p."Номер полиса") AS "Всего полисов" FROM "Клиент" c JOIN "Страховой полис" p ON p."Номер паспорта"=c."Номер паспорта" WHERE EXTRACT(YEAR FROM p."Дата оформления")=EXTRACT(YEAR FROM CURRENT_DATE) GROUP BY c."Номер паспорта",c."ФИО клиента",c."Дата рождения" ORDER BY COUNT(p."Номер полиса") DESC,c."Номер паспорта"''',
'05_Все_клиенты_полисы_текущий_год': '''SELECT c."Номер паспорта",c."ФИО клиента",c."Дата рождения",COUNT(p."Номер полиса") AS "Всего полисов" FROM "Клиент" c LEFT JOIN "Страховой полис" p ON p."Номер паспорта"=c."Номер паспорта" AND EXTRACT(YEAR FROM p."Дата оформления")=EXTRACT(YEAR FROM CURRENT_DATE) GROUP BY c."Номер паспорта",c."ФИО клиента",c."Дата рождения" ORDER BY COUNT(p."Номер полиса") DESC,c."Номер паспорта"''',
'06_Клиенты_максимальное_покрытие': '''SELECT DISTINCT "Номер паспорта","ФИО клиента","Дата рождения","Покрытие полиса","Валюта" FROM "Расчёт полисов" WHERE "Покрытие полиса"=(SELECT MAX("Покрытие полиса") FROM "Расчёт полисов") ORDER BY "Номер паспорта"''',
'07_Клиенты_без_полисов_текущий_год': '''SELECT c."Номер паспорта",c."ФИО клиента",c."Дата рождения" FROM "Клиент" c WHERE NOT EXISTS (SELECT 1 FROM "Страховой полис" p WHERE p."Номер паспорта"=c."Номер паспорта" AND EXTRACT(YEAR FROM p."Дата оформления")=EXTRACT(YEAR FROM CURRENT_DATE)) ORDER BY c."Номер паспорта"''',
'08_Полисы_прошлый_год_для_отчёта': '''SELECT * FROM "Расчёт полисов" WHERE EXTRACT(YEAR FROM "Дата оформления")=EXTRACT(YEAR FROM CURRENT_DATE)-1 ORDER BY "Номер паспорта","Номер полиса"''',
'09_Расчёт_стоимости_полисов': 'SELECT * FROM "Расчёт полисов" ORDER BY "Номер полиса"',
'10_Агенты_количество_за_период': '''SELECT a."Код агента",a."ФИО агента",COUNT(p."Номер полиса") AS "Количество полисов" FROM "Страховой агент" a LEFT JOIN "Договор агента" d ON d."Код агента"=a."Код агента" LEFT JOIN "Страховой полис" p ON p."Номер договора"=d."Номер договора" AND p."Дата оформления">=CAST(:Дата_с AS DATE) AND p."Дата оформления"<=CAST(:Дата_по AS DATE) GROUP BY a."Код агента",a."ФИО агента" ORDER BY a."Код агента"''',
'11_Агенты_выручка_за_период': '''SELECT a."Код агента",a."ФИО агента",COALESCE(SUM(r."Стоимость полиса"),0) AS "Выручка руб",COALESCE(SUM(ROUND(r."Стоимость полиса"*r."Процент комиссии"/100,2)),0) AS "Комиссия руб" FROM "Страховой агент" a LEFT JOIN "Расчёт полисов" r ON r."Код агента"=a."Код агента" AND r."Дата оформления">=CAST(:Дата_с AS DATE) AND r."Дата оформления"<=CAST(:Дата_по AS DATE) GROUP BY a."Код агента",a."ФИО агента" ORDER BY a."Код агента"''',
'13_Средняя_стоимость_за_период': '''SELECT COUNT(*) AS "Количество полисов",CAST(AVG("Стоимость полиса") AS DECIMAL(14,2)) AS "Средняя стоимость руб" FROM "Расчёт полисов" WHERE "Дата оформления">=CAST(:Дата_с AS DATE) AND "Дата оформления"<=CAST(:Дата_по AS DATE)''',
'14_Агенты_средняя_стоимость': '''SELECT a."Код агента",a."ФИО агента",COUNT(r."Номер полиса") AS "Количество полисов",CAST(AVG(r."Стоимость полиса") AS DECIMAL(14,2)) AS "Средняя стоимость руб" FROM "Страховой агент" a LEFT JOIN "Расчёт полисов" r ON r."Код агента"=a."Код агента" AND r."Дата оформления">=CAST(:Дата_с AS DATE) AND r."Дата оформления"<=CAST(:Дата_по AS DATE) GROUP BY a."Код агента",a."ФИО агента" ORDER BY a."Код агента"''',
'15_Услуги_полисов_исторические': '''SELECT j."Номер полиса",u."Код услуги",u."Наименование услуги",k."Наименование категории",j."Дата тарифа",j."Цена услуги" FROM "Услуги в полисе клиента" j JOIN "Услуга" u ON u."Код услуги"=j."Код услуги" JOIN "Справочник категорий услуг" k ON k."Код категории"=u."Код категории" ORDER BY j."Номер полиса",u."Код услуги"''',
'16_Услуги_актуальные_для_списка': '''SELECT u."Код услуги",u."Наименование услуги"||' / '||k."Наименование категории"||' / '||CAST(s."Базовая стоимость" AS VARCHAR(20))||' руб./день' AS "Услуга категория цена" FROM "Услуга" u JOIN "Справочник категорий услуг" k ON k."Код категории"=u."Код категории" JOIN "Стоимость услуг" s ON s."Код услуги"=u."Код услуги" WHERE s."Дата стоимости"=(SELECT MAX(t."Дата стоимости") FROM "Стоимость услуг" t WHERE t."Код услуги"=u."Код услуги" AND t."Дата стоимости"<=CURRENT_DATE) ORDER BY u."Код услуги"''',
'17_Агенты_архив': 'SELECT * FROM "Страховой агент" WHERE "Активен"=0',
'18_Покрытие_максимум_в_рублях': '''SELECT DISTINCT "Номер паспорта","ФИО клиента","Покрытие в рублях" FROM "Расчёт полисов" WHERE "Покрытие в рублях"=(SELECT MAX("Покрытие в рублях") FROM "Расчёт полисов") ORDER BY "Номер паспорта"''',
'19_Полисы_для_слияния_Writer': 'SELECT * FROM "Расчёт полисов" ORDER BY "Номер полиса"',
'20_Договоры_для_слияния_Writer': '''SELECT d.*,a."ФИО агента",a."Паспорт агента",a."Дата выдачи",a."Кем выдан" FROM "Договор агента" d JOIN "Страховой агент" a ON a."Код агента"=d."Код агента" ORDER BY d."Номер договора"'''
}
COUNTS='''SELECT a."Код агента",a."ФИО агента",COUNT(p."Номер полиса") AS "Количество полисов" FROM "Страховой агент" a LEFT JOIN "Договор агента" d ON d."Код агента"=a."Код агента" LEFT JOIN "Страховой полис" p ON p."Номер договора"=d."Номер договора" AND p."Дата оформления">=CAST(:Дата_с AS DATE) AND p."Дата оформления"<=CAST(:Дата_по AS DATE) GROUP BY a."Код агента",a."ФИО агента"'''
QUERIES['12_Агенты_лидеры_за_период']='SELECT z.* FROM ('+COUNTS+') z WHERE z."Количество полисов">0 AND z."Количество полисов"=(SELECT MAX(q."Количество полисов") FROM ('+COUNTS+') q) ORDER BY z."Код агента"'
QUERIES=dict(sorted(QUERIES.items()))
DATA=[]
def val(v):
 if v is None:return 'NULL'
 if isinstance(v,(int,float)):return str(v)
 return "'"+str(v).replace("'","''")+"'"
def insert(table,fields,rows):
 for row in rows:
  DATA.append('INSERT INTO "'+table+'" ('+','.join('"'+f+'"' for f in fields)+') VALUES ('+','.join(val(v) for v in row)+')')
insert('Пол',['Код пола','Наименование пола','Обозначение'],[('1','мужской','M'),('2','женский','F')])
insert('Справочник валют',['Код валюты','Буквенный код','Наименование валюты'],[('978','EUR','Евро'),('840','USD','Доллар США'),('156','CNY','Юань'),('036','AUD','Австралийский доллар')])
for code,old,new in [('978',98,102),('840',90,94),('156',12.50,13.20),('036',59,62)]:
 insert('Курс валюты',['Код валюты','Дата курса','Курс'],[(code,f'{YEAR-1}-01-01',old),(code,f'{YEAR}-01-01',new)])
insert('Справочник стран',['Код ОКСМ','Наименование страны','Код валюты','Страховое покрытие','Коэффициент'],[('276','Германия','978',30000,1.20),('250','Франция','978',50000,1.30),('840','США','840',100000,1.80),('156','Китай','156',50000,1.10),('036','Австралия','036',100000,1.50)])
insert('Справочник категорий услуг',['Код категории','Наименование категории'],[('01','Экстренная помощь'),('02','Транспортировка'),('03','Дополнительная защита')])
services=[('001','01','Неотложная помощь при заболевании',10),('002','01','Стоматологическая помощь',5),('003','01','Помощь при травмах',8),('004','02','Медицинская транспортировка',7),('005','02','Возвращение к месту проживания',4),('006','03','Помощь при занятиях спортом',6)]
for code,category,name,price in services:
 insert('Услуга',['Код услуги','Код категории','Наименование услуги'],[(code,category,name)])
 insert('Стоимость услуг',['Код услуги','Дата стоимости','Базовая стоимость'],[(code,f'{YEAR-1}-01-01',price),(code,f'{YEAR}-01-01',price+2)])
CLIENTS=[('710000001','IVANOV IVAN IVANOVICH','1990-05-12','1'),('710000002','PETROVA ANNA SERGEEVNA','1994-08-21','2'),('710000003','SIDOROV PAVEL OLEGOVICH','1985-02-10','1'),('710000004','SMIRNOVA OLGA PETROVNA','1992-11-03','2'),('710000005','KUZNETSOV EGOR IVANOVICH','1988-07-14','1'),('710000006','VOLKOVA MARIA IGOREVNA','1996-04-22','2'),('710000007','ORLOV NIKITA ANDREEVICH','1991-01-30','1'),('710000008','MOROZOVA ELENA OLEGOVNA','1989-09-17','2')]
insert('Клиент',['Номер паспорта','ФИО клиента','Дата рождения','Код пола','Дата выдачи','Действителен до'],[(*row,f'{YEAR-5}-01-01',f'{YEAR+5}-01-01') for row in CLIENTS])
insert('Страховой агент',['Код агента','ФИО агента','Паспорт агента','Дата выдачи','Кем выдан','Активен'],[(1,'Иванова Елена Павловна','5700000001','2018-02-01','Учебный орган выдачи 1',1),(2,'Соколов Андрей Игоревич','5700000002','2017-05-20','Учебный орган выдачи 2',1),(3,'Петрова Марина Олеговна','5700000003','2019-04-15','Учебный орган выдачи 3',1),(4,'Козлов Илья Сергеевич','5700000004','2020-03-10','Учебный орган выдачи 4',0)])
insert('Договор агента',['Номер договора','Код агента','Дата договора','Начало договора','Окончание договора','Процент комиссии','БИК','Счёт','Наименование банка'],[(f'AG-{i:02d}',i,f'{YEAR-1}-01-01',f'{YEAR-1}-01-01',f'{YEAR+2}-12-31',8+i,'000000000','0000000000000000000'+str(i),'УЧЕБНЫЙ БАНК — НЕДЕЙСТВИТЕЛЬНО') for i in range(1,5)])
# 5 previous-year policies; 8 current-year policies; agents 1 and 2 tie.
POLICIES=[(1,1,YEAR-1,2,10,'276',1,7,['001','002']), (2,1,YEAR-1,6,5,'250',2,10,['001','003','004']), (3,2,YEAR-1,8,15,'840',1,14,['001','003']), (4,6,YEAR-1,9,1,'156',3,7,['001','005']), (5,8,YEAR-1,10,1,'276',2,7,['001','002','005']),
 (6,1,YEAR,1,15,'276',1,7,['001','002']), (7,1,YEAR,2,10,'840',2,14,['001','003','004']), (8,2,YEAR,3,10,'250',1,10,['001','002','005']), (9,3,YEAR,4,5,'156',2,7,['001','006']), (10,4,YEAR,5,20,'036',3,14,['001','003']), (11,5,YEAR,6,1,'840',1,7,['001','004','006']), (12,3,YEAR,7,15,'276',2,10,['001','002']), (13,2,YEAR,8,5,'250',3,7,['001','005'])]
from datetime import timedelta
for pid,ci,year,month,day,country,agent,days,chosen in POLICIES:
 issued=date(year,month,day);begin=issued+timedelta(days=2);end=begin+timedelta(days=days)
 insert('Страховой полис',['Номер полиса','Номер паспорта','Дата оформления','Начало действия','Окончание действия','Код ОКСМ','Номер договора'],[(pid,CLIENTS[ci-1][0],str(issued),str(begin),str(end),country,f'AG-{agent:02d}')])
 insert('Услуги в полисе клиента',['Номер полиса','Код услуги'],[(pid,code) for code in chosen])
DDL += ['ALTER TABLE "Страховой полис" ALTER "Номер полиса" RESTART WITH 14','ALTER TABLE "Страховой агент" ALTER "Код агента" RESTART WITH 5']

# Firebird 3 uses a 31-byte limit for identifiers. Short Latin names keep the
# file portable across LibreOffice builds; the interface/report use Russian.
NAMES={
'Пол':'Gender','Справочник валют':'Currency','Курс валюты':'ExchangeRate','Справочник стран':'Country',
'Справочник категорий услуг':'ServiceCategory','Услуга':'Service','Стоимость услуг':'ServicePrice',
'Клиент':'Client','Страховой агент':'Agent','Договор агента':'AgentContract','Страховой полис':'Policy',
'Услуги в полисе клиента':'PolicyService','Расчёт полисов':'PolicySummary',
'Код пола':'GenderCode','Наименование пола':'GenderName','Обозначение':'GenderSymbol',
'Код валюты':'CurrencyCode','Буквенный код':'AlphaCode','Наименование валюты':'CurrencyName',
'Дата курса':'RateDate','Курс':'Rate','Код ОКСМ':'CountryCode','Наименование страны':'CountryName',
'Страховое покрытие':'Coverage','Коэффициент':'Factor','Код категории':'CategoryCode',
'Наименование категории':'CategoryName','Код услуги':'ServiceCode','Наименование услуги':'ServiceName',
'Дата стоимости':'PriceDate','Базовая стоимость':'BasePrice','Номер паспорта':'PassportNo',
'ФИО клиента':'FullName','Дата рождения':'BirthDate','Дата выдачи':'IssueDate','Действителен до':'ExpiryDate',
'Код агента':'AgentID','ФИО агента':'AgentName','Паспорт агента':'AgentPassport','Кем выдан':'Issuer',
'Активен':'IsActive','Номер договора':'ContractNo','Дата договора':'ContractDate','Начало договора':'ContractStart',
'Окончание договора':'ContractEnd','Процент комиссии':'CommissionPct','БИК':'BankBIK','Счёт':'BankAccount',
'Наименование банка':'BankName','Номер полиса':'PolicyID','Дата оформления':'IssuedOn',
'Начало действия':'StartsOn','Окончание действия':'EndsOn','Коэффициент полиса':'PolicyFactor',
'Покрытие полиса':'PolicyCoverage','Валюта полиса':'PolicyCurrency','Курс полиса':'PolicyRate',
'Дата тарифа':'TariffDate','Цена услуги':'AgreedPrice','Валюта':'CurrencyLabel','Дней':'Days',
'Услуги в день':'DailyServicesRUB','Стоимость полиса':'PremiumRUB','Покрытие в рублях':'CoverageRUB',
'Всего полисов':'PoliciesCount','Количество полисов':'PolicyCount','Выручка руб':'RevenueRUB',
'Комиссия руб':'CommissionRUB','Средняя стоимость руб':'AvgPremiumRUB','Услуга категория цена':'ServiceLabel'}
import re
LABELS={value:key for key,value in NAMES.items()}
def physical(sql):
    return re.sub(r'"([^"\n]+)"',lambda m:'"'+NAMES.get(m.group(1),m.group(1))+'"',sql)
DDL=[physical(sql) for sql in DDL]
DATA=[physical(sql) for sql in DATA]
QUERIES={name:physical(sql) for name,sql in QUERIES.items()}

# Final Base-compatible query definitions are versioned alongside the SQL.
overrides=ROOT/'sql/query_overrides.json'
if overrides.exists():QUERIES.update(json.loads(overrides.read_text()))
service_choices=json.loads((ROOT/'sql/service_choices.json').read_text())['view']
if service_choices:DDL.append('CREATE VIEW "ServiceChoices" AS '+service_choices)

def save_sources():
 (ROOT/'sql').mkdir(exist_ok=True)
 # JSON retains statement boundaries for trigger bodies.
 (ROOT/'sql'/'schema.json').write_text(json.dumps(DDL,ensure_ascii=False,indent=2))
 (ROOT/'sql'/'schema.sql').write_text('-- Firebird 3.0+, script for isql. UNO uses the statement boundaries in schema.json.\n'+'\n\n'.join(('SET TERM ^ ;\n'+sql+'^\nSET TERM ; ^') if sql.startswith('CREATE TRIGGER') else (sql+';') for sql in DDL)+'\n')
 (ROOT/'sql'/'data.sql').write_text('-- Все персональные и финансовые данные вымышлены; курсы учебные.\n'+';\n'.join(DATA)+';\n')
 (ROOT/'sql'/'queries.json').write_text(json.dumps(QUERIES,ensure_ascii=False,indent=2))
 (ROOT/'sql'/'queries.sql').write_text('\n\n'.join('-- '+name+'\n'+sql+';' for name,sql in QUERIES.items())+'\n')
if __name__=='__main__':
 save_sources()
 print('Prepared',len(DDL),'DDL statements,',len(DATA),'data statements,',len(QUERIES),'saved queries')
